td.p:
In principle, specifying "HE" or "PE" will
                  inhibit optimizations that generate code which Saxon-HE/Saxon-PE cannot execute;
                  however, this is not fully tested.

pre.code:
Processor processor = new Processor(false);
XsltCompiler compiler = processor.newXsltCompiler();
XsltExecutable stylesheet = compiler.compile(new StreamSource(new File("styles/books.xsl")));
Serializer out = processor.newSerializer(new File("books.html"));
out.setOutputProperty(Serializer.Property.METHOD, "html");
out.setOutputProperty(Serializer.Property.INDENT, "yes");
Xslt30Transformer transformer = stylesheet.load30();
transformer.transform(new StreamSource(new File("data/books.xml")), out);

var transformer = executable.Load();
transformer.SetInputStream(...);
transformer.SetParameter(new QName("debug"), new XdmAtomicValue(true));
var writer = new StringWriter();
var serializer = processor.NewSerializer(writer);
serializer.SetOutputProperty(Serializer.INDENT, "yes");
transformer.Run(serializer);
Console.WriteLine(writer.ToString());

// Create a Processor instance.
Processor processor = new();

// Load the source document
XdmNode input = processor.NewDocumentBuilder().Build(new Uri(samplesDir, "data/books.xml"));

// Create a transformer for the stylesheet
Xslt30Transformer transformer = processor.NewXsltCompiler().Compile(new Uri(samplesDir, 
   "styles/identity.xsl")).Load30();

// Create a serializer
const string outfile = "OutputFromXsltSimple2.xml";
Serializer serializer = processor.NewSerializer();
serializer.OutputStream = new FileStream(outfile, FileMode.Create, FileAccess.Write);

// Transform the source XML and serialize the result to the output file.
transformer.ApplyTemplates(input, serializer);

Console.WriteLine("\nOutput written to " + outfile + "\n");

int cap = 10;
sxnc_parameter *parameters;
int parLen = 0, parCap;
parCap = cap;
sxnc_property *properties;
int propLen = 0;
parCap = cap;
sxnc_environment *environ;
sxnc_processor *processor;

initSaxonc(&environ, &processor, &parameters, &properties, parCap, parCap);

executable->setSaveXslMessage(true);
result = executable->transformToString();
XdmValue * messages = executable->getXslMessages();

section.aside:
Older interfaces for processing messages remain available for backwards compatibility;
         but from 11.1, the -m option on the command line is ignored, as is the
            configuration property .
